use symbolica::domains::float::FloatField;
use symbolica::prelude::*;
use symbolica_amflow::{Precision, Result};

fn symbol(name: &str) -> Symbol {
    match Atom::parse(name, "parameter_specialization_mre", Default::default())
        .unwrap()
        .as_view()
    {
        AtomView::Var(v) => v.get_symbol(),
        _ => unreachable!(),
    }
}

fn main() -> Result<()> {
    let a = Atom::var(symbol("a"));
    let b = Atom::var(symbol("b"));
    let coefficient = a.clone().pow(2) - &b;
    let high = Precision::decimal(300)?;
    let exact_a = Rational::from(Integer::from(2).pow(400));
    let exact_b = &exact_a * &exact_a - Rational::one();
    let numeric = ahash::HashMap::from_iter([
        (a.clone(), high.rational(&exact_a)),
        (b.clone(), high.rational(&exact_b)),
    ]);
    assert_eq!(numeric[&a].re.to_rational(), exact_a);
    assert_eq!(numeric[&b].re.to_rational(), exact_b);
    let exact_values = ahash::HashMap::from_iter([
        (a, Complex::new(exact_a, Rational::zero())),
        (b, Complex::new(exact_b, Rational::zero())),
    ]);
    let gaussian_ring = FloatField::from_rep(Complex::new(Rational::zero(), Rational::zero()));
    let exact = coefficient
        .evaluate_in_ring(&exact_values, &gaussian_ring)
        .unwrap();
    assert_eq!(exact, Complex::new(Rational::one(), Rational::zero()));
    let mut profiles = Vec::new();
    for working in [60, 100, 200, 260] {
        let p = Precision::decimal(working)?;
        let evaluated = p.eval(&coefficient, &numeric)?;
        let stored_derivative =
            Complex::new(evaluated.re.to_rational(), evaluated.im.to_rational());
        let exact_defect = stored_derivative - &exact;
        profiles.push(serde_json::json!({
            "working_digits":working,"working_bits":p.bits,
            "float_evaluation":evaluated.to_string(),
            "exact_source_value":exact.to_string(),
            "exact_constant_differential_defect":exact_defect.to_string(),
        }));
    }
    println!("{}", serde_json::to_string_pretty(&serde_json::json!({
        "scope":"Native Float versus Gaussian parameter specialization; exact coefficient discrepancy, no endpoint transport or verified-digit claim.",
        "expression":"a^2-b", "exact_parameters":"a=2^400,b=2^800-1 supplied as exactly represented 300-digit Floats",
        "system":"Y1prime=(a^2-b)*Y2,Y2prime=0,Y(0)=[0,1]",
        "exact_solution":"Y(x)=[x,1]", "profiles":profiles,
    })).unwrap());
    Ok(())
}
